def evaluate(store, task, profile, compute):
    # Check owner mismatch first
    if task['owner'] != profile['owner']:
        raise PermissionError("Owner mismatch")

    # Check version mismatch
    if task['version'] != profile['version']:
        return None

    # Create cache key including all required components
    key = (task['owner'], profile['version'], task['criteria_version'], task['job_text'])

    # If key not in store, compute and cache the result
    if key not in store:
        try:
            result = compute()
            store[key] = result
        except Exception as e:
            # Propagate exceptions without caching them
            raise e

    return store[key]

import service

def test_basic_functionality():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': 'test_job', 'criteria_version': 1}
    profile = {'owner': 'alice', 'version': 1}

    def compute():
        return 'result'

    result = service.evaluate(store, task, profile, compute)
    assert result == 'result'
    assert store[('alice', 1, 1, 'test_job')] == 'result'


def test_owner_mismatch_raises_permission_error():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': 'test_job', 'criteria_version': 1}
    profile = {'owner': 'bob', 'version': 1}

    def compute():
        return 'result'

    try:
        service.evaluate(store, task, profile, compute)
        assert False, "Should have raised PermissionError"
    except PermissionError:
        pass


def test_version_mismatch_returns_none():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': 'test_job', 'criteria_version': 1}
    profile = {'owner': 'alice', 'version': 2}

    def compute():
        return 'result'

    result = service.evaluate(store, task, profile, compute)
    assert result is None
    assert len(store) == 0


def test_cache_reuse():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': 'test_job', 'criteria_version': 1}
    profile = {'owner': 'alice', 'version': 1}

    call_count = 0
    def compute():
        nonlocal call_count
        call_count += 1
        return f'result_{call_count}'

    # First call - should compute and cache
    result1 = service.evaluate(store, task, profile, compute)
    assert result1 == 'result_1'

    # Second call - should reuse from cache
    result2 = service.evaluate(store, task, profile, compute)
    assert result2 == 'result_1'
    assert call_count == 1  # Compute should only be called once


def test_exception_propagation():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': 'test_job', 'criteria_version': 1}
    profile = {'owner': 'alice', 'version': 1}

    def compute():
        raise ValueError("Compute error")

    try:
        service.evaluate(store, task, profile, compute)
        assert False, "Should have raised ValueError"
    except ValueError as e:
        assert str(e) == "Compute error"

    # Verify that exception was not cached
    assert len(store) == 0


def test_none_and_zero_values():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': None, 'criteria_version': 0}
    profile = {'owner': 'alice', 'version': 1}

    def compute():
        return 'result'

    result = service.evaluate(store, task, profile, compute)
    assert result == 'result'

    # Test that same None/0 values reuse cache
    result2 = service.evaluate(store, task, profile, compute)
    assert result2 == 'result'


def test_different_criteria_versions():
    store = {}
    task1 = {'owner': 'alice', 'version': 1, 'job_text': 'test_job', 'criteria_version': 1}
    task2 = {'owner': 'alice', 'version': 1, 'job_text': 'test_job', 'criteria_version': 2}
    profile = {'owner': 'alice', 'version': 1}

    call_count = 0
    def compute():
        nonlocal call_count
        call_count += 1
        return f'result_{call_count}'

    # First call with criteria_version=1
    result1 = service.evaluate(store, task1, profile, compute)
    assert result1 == 'result_1'

    # Second call with criteria_version=2 - should compute again
    result2 = service.evaluate(store, task2, profile, compute)
    assert result2 == 'result_2'
    assert call_count == 2  # Compute called twice


def run_all_tests():
    test_basic_functionality()
    test_owner_mismatch_raises_permission_error()
    test_version_mismatch_returns_none()
    test_cache_reuse()
    test_exception_propagation()
    test_none_and_zero_values()
    test_different_criteria_versions()
    print("All tests passed!")

if __name__ == "__main__":
    run_all_tests()
